#!/usr/bin/env python3
"""pty2.py [--stdin-tty] [--env K=V|--unset K]... -- cmd args...
Runs cmd with stdout on a pty. stdin: pty if --stdin-tty, else file/pipe from --stdin-file or /dev/null."""
import os, pty, sys, subprocess, argparse, tty, termios

args = sys.argv[1:]
env = dict(os.environ)
stdin_tty = False
stdin_file = None
while args and args[0] != '--':
    a = args.pop(0)
    if a == '--stdin-tty': stdin_tty = True
    elif a == '--env': k,v = args.pop(0).split('=',1); env[k]=v
    elif a == '--unset': env.pop(args.pop(0), None)
    elif a == '--stdin-file': stdin_file = args.pop(0)
    elif a == '--stderr-tty': pass
    else: raise SystemExit("bad opt "+a)
if args and args[0]=='--': args.pop(0)

mo, so = pty.openpty()
if stdin_tty:
    mi, si = pty.openpty()
    stdin_arg = si
else:
    if stdin_file:
        stdin_arg = open(stdin_file, 'rb')
    else:
        stdin_arg = subprocess.DEVNULL

p = subprocess.Popen(args, stdout=so, stderr=subprocess.PIPE, stdin=stdin_arg, env=env)
os.close(so)
if stdin_tty: os.close(si)
out = b""
while True:
    try:
        d = os.read(mo, 65536)
    except OSError: break
    if not d: break
    out += d
p.wait()
os.close(mo)
if stdin_tty: os.close(mi)
err = p.stderr.read()
sys.stdout.write("STDOUT: " + repr(out) + "\n")
sys.stdout.write("STDERR: " + repr(err) + "\n")
sys.stdout.write("exit=%d\n" % p.returncode)
EOF
cd /tmp/probe/work-cli && python3 pty2.py --unset NO_COLOR --env TERM=xterm --stdin-file a.json -- /workspace/executable

